<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { profileApi } from '../api/profile'
const customers=ref<any[]>([]),selected=ref(''),recommendation=ref<any>(null),selectedProduct=ref(''),amount=ref<number|undefined>(),error=ref(''),loading=ref(true),working=ref(false),draftWorking=ref(false)
async function load(){try{customers.value=(await profileApi.advisorCustomers('', '', '', 100, 0)).data.data.items}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{loading.value=false}}
async function recommend(){if(!selected.value)return;working.value=true;try{recommendation.value=(await profileApi.staffRecommendations(selected.value)).data.data}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{working.value=false}}
async function createDraft(){if(!selected.value||!selectedProduct.value||!amount.value)return;draftWorking.value=true;try{await profileApi.createStaffOperationDraft({customer_id:selected.value,product_id:selectedProduct.value,amount:amount.value,note:'工作人员推荐草稿'});error.value='操作草稿已创建，等待客户确认'}catch(e:any){error.value=e.response?.data?.detail?.message||e.message}finally{draftWorking.value=false}}
onMounted(load)
</script>
<template><section class="workspace-page"><div class="section-heading"><div><span class="eyebrow">ADVISOR DESK</span><h2>投顾工作台</h2><p>仅显示当前投顾已获得客户授权的客户。授权生效后，才可查看适当性推荐并创建待客户确认的操作草稿。</p></div><span class="pill">工作人员</span></div><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="empty">正在读取客户…</div><template v-else><div class="panel-card"><div class="row-actions"><select v-model="selected" class="advisor-select"><option value="">请选择已授权客户</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.display_name}}（{{c.username}}）</option></select><button class="button" :disabled="!selected||working" @click="recommend">{{working?'分析中':'生成推荐'}}</button></div></div><div v-if="!customers.length" class="panel-card empty">当前没有已授权客户。请先由客户在客户中心选择并授权您。</div><div v-if="recommendation" class="panel-card"><h3>适当性推荐</h3><div v-for="item in recommendation.matches" :key="item.product_id" class="list-row"><div><strong>{{item.product_name}}</strong><small>产品ID：{{item.product_id}} · {{item.reasons?.join('；')}}</small></div><span class="status-badge active">匹配</span></div><div v-if="!recommendation.matches?.length" class="empty">暂无匹配产品</div><div v-else class="draft-form"><select v-model="selectedProduct" class="advisor-select"><option value="">选择推荐产品</option><option v-for="item in recommendation.matches" :key="item.product_id" :value="item.product_id">{{item.product_name}}</option></select><input v-model.number="amount" type="number" min="1" placeholder="金额" /><button class="button" :disabled="!selectedProduct||!amount||draftWorking" @click="createDraft">{{draftWorking?'创建中':'创建客户确认草稿'}}</button></div></div></template></section></template>
